BEGIN;

-- Ficha de Vickiana.
--
-- Campos, cada uno con dos fuentes:
--  * Nombre legal Ana Victoria García Pérez: MusicBrainz (Legal name) y Wikipedia.
--  * province pasa de Distrito Nacional a Santiago: birth_place ya decía
--    Santiago de los Caballeros; MusicBrainz y Wikipedia coinciden.
--  * instagram vickiana_official; occupations television_host y actress.
--
-- Nueva categoría Casandra "Cantante Popular": es la categoría literal de la
-- primera edición (1985), sin género — su terna fue Anthony Ríos, Olga Lara y
-- Vickiana — y no hay equivalente en el catálogo.
--
-- Sin registrar por fuente única (Wikipedia, y un espejo que la copia):
-- El Dorado 1981/1983/1984, El Gordo 1984-1986, Casandra 1989 como cantante
-- femenina y espectáculo, Trabucazo, Cotorra, Master, ACE 1990.
--
-- Fuera: matrimonios, hijos, cardiopatía, coma diabético de 2011 y el caso
-- judicial de 2013 (vida personal, salud, asuntos legales ajenos a la música).

UPDATE artists SET first_name = 'Ana', middle_name = 'Victoria', last_name = 'García', second_last_name = 'Pérez',
       province = 'Santiago', instagram = 'vickiana_official', occupations = '["television_host","actress"]'::jsonb
 WHERE slug = 'vickiana';

INSERT INTO award_categories (award_id, name)
SELECT a.id, 'Cantante Popular' FROM awards a WHERE a.name = 'Premios Casandra'
   AND NOT EXISTS (SELECT 1 FROM award_categories c WHERE c.award_id = a.id AND c.name = 'Cantante Popular');
INSERT INTO artist_awards (artist_id, award_id, category_id, year, work, won, source)
SELECT ar.id, cat.award_id, cat.id, 1985, NULL, true, 'Artículo de la edición Premios Casandra 1985 (ganadora marcada) y Wikipedia (es) de la artista; primera entrega, 15 de abril de 1985, Cine Olimpia'
  FROM artists ar, award_categories cat JOIN awards a ON a.id = cat.award_id
 WHERE ar.slug = 'vickiana' AND a.name = 'Premios Casandra' AND cat.name = 'Cantante Popular'
   AND NOT EXISTS (SELECT 1 FROM artist_awards w WHERE w.artist_id = ar.id AND w.category_id = cat.id AND w.year = 1985);
INSERT INTO artist_awards (artist_id, award_id, category_id, year, work, won, source)
SELECT ar.id, cat.award_id, cat.id, 2015, NULL, true, 'Hoy y La Crónica; ceremonia del 14 de abril de 2015, entregado junto a Olga Lara'
  FROM artists ar, award_categories cat JOIN awards a ON a.id = cat.award_id
 WHERE ar.slug = 'vickiana' AND a.name = 'Premios Soberano' AND cat.name = 'Soberano al Mérito'
   AND NOT EXISTS (SELECT 1 FROM artist_awards w WHERE w.artist_id = ar.id AND w.category_id = cat.id AND w.year = 2015);

